tool_arguments.query:
SELECT u.username, f.id, f.title, f.file, f.created_at
FROM files_uploadedfile f
JOIN auth_user u ON u.id = (
    SELECT id FROM auth_user WHERE username ILIKE 'bob' LIMIT 1
)
WHERE f.id IN (
    SELECT id FROM files_uploadedfile
)
ORDER BY f.created_at;

